import React from 'react';

const FilterAccordion = ({ title, showArrow = true }) => {
    return (
        <div className="flex justify-between items-center py-4 border-b border-transparent hover:bg-gray-50 cursor-pointer">
            <span className="text-xs tracking-wider text-gray-800 font-medium font-display">{title}</span>
            {showArrow ? (
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 text-gray-800">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3" />
                </svg>
            ) : (
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 text-gray-800">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
                </svg>
            )}
        </div>
    );
};

const FilterSidebar = ({ isOpen, onClose, totalResults = 0 }) => {
    return (
        <>
            {/* Overlay */}
            {isOpen && (
                <div 
                    className="fixed inset-0 bg-black/30 backdrop-blur-[1px] z-40 transition-opacity"
                    onClick={onClose}
                />
            )}

            {/* Sidebar Drawer */}
            <div 
                className={`fixed top-0 right-0 h-full w-[400px] max-w-full bg-white shadow-2xl z-50 transform transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] flex flex-col font-display ${
                    isOpen ? 'translate-x-0' : 'translate-x-full'
                }`}
            >
                {/* Header */}
                <div className="flex items-center justify-between px-6 py-5 border-b border-[#f1f1f1]">
                    <span className="text-xs uppercase tracking-[0.2em] font-medium opacity-0">SPACER</span> {/* Invisible spacer for flex layout centering */}
                    <h2 className="text-xs uppercase tracking-[0.2em] font-medium text-gray-900 absolute left-1/2 -translate-x-1/2">
                        Filter
                    </h2>
                    <button 
                        onClick={onClose}
                        className="text-gray-900 hover:text-gray-500 transition-colors p-2"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18 18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>

                {/* Body (Scrollable) */}
                <div className="flex-1 overflow-y-auto px-6 py-6">

                    {/* Price Range */}
                    <div className="mb-10 block">
                        <div className="flex justify-between items-center mb-6">
                            <span className="text-xs tracking-wider text-gray-800 font-bold">PRICE RANGE</span>
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                              <path strokeLinecap="round" strokeLinejoin="round" d="M5 12h14" />
                            </svg>
                        </div>
                        <div className="flex justify-between items-center text-[10px] font-bold text-gray-900 mb-2">
                            <span>499.00 Rs</span>
                            <span>7999.00 Rs</span>
                        </div>
                        {/* Mock Range Slider */}
                        <div className="relative w-full h-0.5 bg-gray-200 rounded">
                            <div className="absolute left-0 right-0 h-full bg-black"></div>
                            <div className="absolute left-0 top-1/2 -translate-y-1/2 w-4 h-4 bg-black rounded-sm border-2 border-white shadow cursor-pointer"></div>
                            <div className="absolute right-0 top-1/2 -translate-y-1/2 w-4 h-4 bg-black rounded-sm border-2 border-white shadow cursor-pointer"></div>
                        </div>
                    </div>

                    {/* Accordions */}
                    <div className="space-y-2">
                        <FilterAccordion title="COLOUR" />
                        <FilterAccordion title="SIZE" />
                        <FilterAccordion title="PRODUCT TYPE" />
                        <FilterAccordion title="STYLE" />
                        <FilterAccordion title="FIT" />
                        <FilterAccordion title="MATERIAL" />
                        <FilterAccordion title="MORE FILTERS" showArrow={false} />
                    </div>
                </div>

                {/* Footer fixed */}
                <div className="p-6 border-t border-[#f1f1f1] bg-white grid grid-cols-2 gap-4">
                    <button 
                        className="py-4 text-[11px] font-bold tracking-[0.1em] text-gray-500 bg-[#f4f4f4] hover:bg-gray-200 transition-colors uppercase leading-none"
                    >
                        Clear
                    </button>
                    <button 
                        onClick={onClose}
                        className="py-4 text-[11px] font-bold tracking-[0.1em] text-white bg-black hover:bg-gray-800 transition-colors uppercase leading-none shadow-xl"
                    >
                        View [{totalResults}]
                    </button>
                </div>
            </div>
        </>
    );
};

export default FilterSidebar;
